// Reagent Wave. Time is in seconds and the scene loops every 20 seconds.
// UHD export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintReagentWave = (() => {
  const tau = 2 * Math.PI;
  const violet = "#BB72FF";
  const apricot = "#FFA476";
  const cream = "#FFE1D2";

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  const bottle = new Path2D();
  bottle.moveTo(-76, -299);
  const points = [{ x: -76, y: -299, length: 0 }];
  const spans = [
    [76, -299], [91, -299, 91, -285], [91, -268], [91, -253, 75, -253],
    [63, -253], [63, -150], [63, -128, 80, -104], [244, 196],
    [266, 237, 238, 265], [219, 285, 185, 285], [-185, 285],
    [-219, 285, -238, 265], [-266, 237, -244, 196], [-80, -104],
    [-63, -128, -63, -150], [-63, -253], [-75, -253], [-91, -253, -91, -268],
    [-91, -285], [-91, -299, -76, -299]
  ];

  for (const span of spans) {
    const start = points[points.length - 1];
    const curve = span.length === 4;
    if (curve) bottle.quadraticCurveTo(...span);
    else bottle.lineTo(...span);
    const count = curve ? 44 : 1;
    for (let i = 1; i <= count; i++) {
      const u = i / count;
      const v = 1 - u;
      const x = curve ? v * v * start.x + 2 * u * v * span[0] + u * u * span[2] : span[0];
      const y = curve ? v * v * start.y + 2 * u * v * span[1] + u * u * span[3] : span[1];
      const last = points[points.length - 1];
      points.push({ x, y, length: last.length + Math.hypot(x - last.x, y - last.y) });
    }
  }
  bottle.closePath();
  const rimLength = points[points.length - 1].length;

  const well = new Path2D(
    "M -43 -227 H 43 V -151 Q 43 -125 55 -100 L 203 178 Q 227 222 211 242 " +
    "Q 200 258 176 258 H -176 Q -200 258 -211 242 Q -227 222 -203 178 " +
    "L -55 -100 Q -43 -125 -43 -151 Z"
  );
  const mouth = new Path2D();
  mouth.roundRect(-69, -285, 138, 17, 8);
  const mouthTrim = new Path2D("M -37 -276.5 H 37");
  const baseTrim = new Path2D("M -48 272 H 48");

  const measures = [];
  for (const side of [-1, 1]) {
    for (let i = 0; i < 6; i++) {
      const y = -24 + 36 * i;
      const wellX = 55 + 148 * (y + 100) / 278;
      const start = wellX + 7;
      const path = new Path2D();
      path.moveTo(side * start, y);
      path.lineTo(side * (start + (i % 2 === 0 ? 11.5 : 8)), y);
      measures.push({ path, x: side * wellX, y });
    }
  }

  function pointAt(distance) {
    let low = 0;
    let high = points.length - 1;
    while (high - low > 1) {
      const middle = (low + high) >>> 1;
      if (points[middle].length <= distance) low = middle;
      else high = middle;
    }
    const a = points[low];
    const b = points[high];
    const u = (distance - a.length) / (b.length - a.length);
    return { x: a.x + u * (b.x - a.x), y: a.y + u * (b.y - a.y), next: high };
  }

  function rimTrail(ctx, head, power, unit) {
    const to = head % rimLength;
    const from = (to + rimLength - 117) % rimLength;
    const wraps = from > to;
    const a = pointAt(from);
    const b = pointAt(to);
    const path = new Path2D();
    path.moveTo(a.x, a.y);
    const stop = wraps ? points.length : b.next;
    for (let i = a.next; i < stop; i++) path.lineTo(points[i].x, points[i].y);
    if (wraps) {
      for (let i = 1; i < b.next; i++) path.lineTo(points[i].x, points[i].y);
    }
    path.lineTo(b.x, b.y);

    const tint = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
    tint.addColorStop(0, "rgba(187,114,255,0)");
    tint.addColorStop(0.42, "rgba(187,114,255,0.28)");
    tint.addColorStop(0.81, violet);
    tint.addColorStop(1, "#F0D9FF");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(187,114,255,0.76)";
    ctx.shadowBlur = 17 * unit;
    stroke(ctx, path, 5.55, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.1, tint);
    ctx.restore();
  }

  // Opposite carriers travel along two interfaces with a fixed minimum separation.
  function surfaceHeight(x, progress, level, activity, packet, upper) {
    const direction = upper ? 1 : -1;
    const u = x / 442;
    const travel = tau * (1.13 * u - direction * 3 * progress);
    const focus = 1 - ease(26, 140, Math.abs(x - direction * packet));
    const amplitude = 4.1 + activity * (2.8 + 7.4 * focus);
    const offset = upper ? 0 : 58 + 2.5 * Math.sin(tau * progress);
    return level + offset
      + amplitude * Math.sin(travel + (upper ? 0.45 : 1.76))
      + 1.7 * Math.sin(2 * travel - direction * 0.4);
  }

  function liquid(ctx, progress, level, activity, packet, unit) {
    const top = new Path2D();
    const divider = new Path2D();
    const warm = new Path2D();
    const upperEdge = [];
    const lowerEdge = [];
    for (let i = 0; i <= 112; i++) {
      const x = -246 + 492 * i / 112;
      upperEdge.push([x, surfaceHeight(x, progress, level, activity, packet, true)]);
      lowerEdge.push([x, surfaceHeight(x, progress, level, activity, packet, false)]);
    }

    top.moveTo(...upperEdge[0]);
    divider.moveTo(...lowerEdge[0]);
    warm.moveTo(lowerEdge[0][0], lowerEdge[0][1] + 1.9);
    for (let i = 1; i < upperEdge.length; i++) {
      top.lineTo(...upperEdge[i]);
      divider.lineTo(...lowerEdge[i]);
      warm.lineTo(lowerEdge[i][0], lowerEdge[i][1] + 1.9);
    }

    const cool = new Path2D(top);
    for (let i = lowerEdge.length - 1; i >= 0; i--) cool.lineTo(lowerEdge[i][0], lowerEdge[i][1] - 1.9);
    cool.closePath();
    warm.lineTo(246, 276);
    warm.lineTo(-246, 276);
    warm.closePath();

    ctx.save();
    ctx.clip(well);
    const lowerTint = ctx.createLinearGradient(0, level + 39, 0, 258);
    lowerTint.addColorStop(0, "#683838");
    lowerTint.addColorStop(0.36, "#482436");
    lowerTint.addColorStop(1, "#2A172A");
    ctx.fillStyle = lowerTint;
    ctx.fill(warm);

    const upperTint = ctx.createLinearGradient(0, level - 16, 0, level + 73);
    upperTint.addColorStop(0, "#603B72");
    upperTint.addColorStop(0.42, "#432450");
    upperTint.addColorStop(1, "#321B42");
    ctx.fillStyle = upperTint;
    ctx.fill(cool);

    ctx.shadowBlur = 12 * unit;
    ctx.shadowColor = "rgba(187,114,255,0.71)";
    stroke(ctx, top, 3.15, violet);
    ctx.shadowColor = "rgba(255,164,118,0.59)";
    stroke(ctx, divider, 2.75, apricot);
    ctx.shadowBlur = 0;

    for (const [path, center, highlight] of [[top, packet, "#F5DBFF"], [divider, -packet, cream]]) {
      const sheen = ctx.createLinearGradient(center - 87, 0, center + 87, 0);
      sheen.addColorStop(0, "rgba(255,225,235,0)");
      sheen.addColorStop(0.5, highlight);
      sheen.addColorStop(1, "rgba(255,225,235,0)");
      ctx.globalAlpha = 0.81 * activity;
      stroke(ctx, path, 1.9, sheen);
    }
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#2A1732";
    ctx.fill(bottle);
    ctx.shadowColor = "rgba(187,114,255,0.27)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, bottle, 4.3, "#8B54AD");
    ctx.shadowBlur = 0;
    stroke(ctx, bottle, 1.35, "#D19CF0");

    ctx.fillStyle = "#211227";
    ctx.fill(mouth);
    ctx.fill(well);
    stroke(ctx, mouth, 1.9, "#8D5EA6");
    stroke(ctx, mouthTrim, 1.6, "#AA77C4");
    stroke(ctx, baseTrim, 1.7, "#794F88");

    const volume = ease(0, 6, seconds) * (1 - ease(14, 20, seconds));
    const activity = envelope(seconds, 3.8, 6.7, 13.25, 16.9);
    const packet = -258 + 516 * ease(5.12, 14.88, seconds);
    const level = 104 - 103 * volume;
    liquid(ctx, progress, level, activity, packet, unit);
    stroke(ctx, well, 1.9, "#684276");

    for (const measure of measures) {
      const crossing = measure.y - surfaceHeight(measure.x, progress, level, activity, packet, true);
      const power = 0.65 * (1 - ease(2.2, 19, Math.abs(crossing))) + 0.12 * ease(4, 26, crossing);
      stroke(ctx, measure.path, 1.7, "#8D5DA0");
      ctx.globalAlpha = power;
      stroke(ctx, measure.path, 2.1, "#F0CEFF");
      ctx.globalAlpha = 1;
    }

    const wallPower = 0.48 + 0.40 * (1 - envelope(seconds, 3.6, 6.2, 13.95, 16.7));
    const head = ((progress + 0.16) % 1) * rimLength;
    rimTrail(ctx, head, wallPower, unit);
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(minSide / 1000, width / 650);

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#1B0D22";
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width * 0.5, height * 0.507);
  ctx.scale(unit, unit);
  paintReagentWave(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Wind Harmonics. Time is in seconds and the scene loops every 20 seconds.
// UHD export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintWindHarmonics = (() => {
  const tau = 2 * Math.PI;
  const aqua = "#2CF2CE";
  const citron = "#DAFF73";
  const rotorY = -106;
  const gustPhase = tau * 0.45;

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  function circle(radius) {
    const path = new Path2D();
    path.arc(0, 0, radius, 0, tau);
    path.closePath();
    return path;
  }

  function rail(x, y, curve) {
    const path = new Path2D();
    path.moveTo(x, y);
    path.bezierCurveTo(...curve);
    const points = [{ x, y, length: 0 }];
    const count = 60;
    for (let i = 1; i <= count; i++) {
      const u = i / count;
      const v = 1 - u;
      const nextX = v ** 3 * x + 3 * v * v * u * curve[0] + 3 * v * u * u * curve[2] + u ** 3 * curve[4];
      const nextY = v ** 3 * y + 3 * v * v * u * curve[1] + 3 * v * u * u * curve[3] + u ** 3 * curve[5];
      const last = points[points.length - 1];
      points.push({ x: nextX, y: nextY, length: last.length + Math.hypot(nextX - last.x, nextY - last.y) });
    }
    return { path, points, length: points[points.length - 1].length };
  }

  function pointAt(points, distance) {
    let low = 0;
    let high = points.length - 1;
    while (high - low > 1) {
      const middle = (low + high) >>> 1;
      if (points[middle].length <= distance) low = middle;
      else high = middle;
    }
    const a = points[low];
    const b = points[high];
    const u = (distance - a.length) / (b.length - a.length);
    return { x: a.x + u * (b.x - a.x), y: a.y + u * (b.y - a.y), next: high };
  }

  function trail(ctx, track, head, tail, power, unit, weight) {
    const from = Math.max(0, head - tail);
    const to = Math.min(head, track.length);
    if (power < 0.001 || to - from < 0.15) return;

    const a = pointAt(track.points, from);
    const b = pointAt(track.points, to);
    const path = new Path2D();
    path.moveTo(a.x, a.y);
    for (let i = a.next; i < b.next; i++) path.lineTo(track.points[i].x, track.points[i].y);
    path.lineTo(b.x, b.y);

    const tint = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
    tint.addColorStop(0, "rgba(44,242,206,0)");
    tint.addColorStop(0.43, "rgba(44,242,206,0.30)");
    tint.addColorStop(0.83, aqua);
    tint.addColorStop(1, citron);
    const core = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
    core.addColorStop(0, "rgba(218,255,115,0)");
    core.addColorStop(0.65, "rgba(218,255,115,0.34)");
    core.addColorStop(1, "#E7FFCB");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(44,242,206,0.72)";
    ctx.shadowBlur = 13 * unit * weight;
    stroke(ctx, path, 4.7 * weight, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 1.95 * weight, core);
    ctx.restore();
  }

  const airflow = [
    { track: rail(-505, -112, [-430, -134, -363, -80, -276, -91]), delay: 0.12, gain: 0.69 },
    { track: rail(-524, 0, [-443, -23, -357, 18, -273, 0]), delay: 0, gain: 1 },
    { track: rail(-497, 113, [-426, 134, -353, 76, -278, 89]), delay: 0.27, gain: 0.64 },
    { track: rail(276, -89, [351, -114, 439, -65, 504, -88]), delay: 2.52, gain: 0.62 },
    { track: rail(273, 3, [353, -13, 441, 25, 524, 4]), delay: 2.39, gain: 0.90 },
    { track: rail(278, 89, [354, 63, 431, 117, 500, 100]), delay: 2.65, gain: 0.59 }
  ];

  // The rotor only applies rigid rotation to the three identical blades.
  const blade = new Path2D(
    "M 41 -11 C 68 -29 103 -30 139 -24 C 175 -20 209 -10 230 -1 " +
    "Q 241 4 229 12 C 201 27 158 32 116 28 Q 72 24 42 12 Q 32 8 41 -11 Z"
  );
  const bladeLane = rail(54, 0, [94, -7, 169, -6, 217, 6]);
  const hub = circle(25);
  const hubInset = circle(16);
  const hubCenter = circle(4.2);
  const hubTicks = new Path2D();
  for (let i = 0; i < 3; i++) {
    const angle = i * tau / 3;
    hubTicks.moveTo(18.8 * Math.cos(angle), 18.8 * Math.sin(angle));
    hubTicks.lineTo(21.8 * Math.cos(angle), 21.8 * Math.sin(angle));
  }

  const frame = new Path2D();
  const frameRadius = 255;
  const frameGap = 0.46;
  frame.arc(0, rotorY, frameRadius, frameGap, Math.PI - frameGap);
  const upperStart = Math.PI + frameGap;
  frame.moveTo(frameRadius * Math.cos(upperStart), rotorY + frameRadius * Math.sin(upperStart));
  frame.arc(0, rotorY, frameRadius, upperStart, tau - frameGap);
  const mast = new Path2D(
    "M -22 157 Q 0 163 22 157 L 36 293 Q 38 305 49 305 H 73 Q 83 305 83 316 " +
    "V 320 Q 83 332 71 332 H -71 Q -83 332 -83 320 V 316 Q -83 305 -73 305 " +
    "H -49 Q -38 305 -36 293 Z"
  );
  const mastRail = new Path2D("M 0 203 V 285 M -47 318 H -26 M 26 318 H 47");
  const mastStatus = new Path2D("M -10 318 H 10");

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#102822";
    ctx.fill(mast);
    stroke(ctx, mast, 3.1, "#4B9B86");
    stroke(ctx, frame, 2.0, "#377568");
    stroke(ctx, mastRail, 1.85, "#397B6D");
    stroke(ctx, mastStatus, 2.15, "#5CA991");

    const gust = (seconds + 5) % 5;
    ctx.globalAlpha = 0.66 * envelope(gust, 2.44, 2.82, 3.12, 3.86);
    stroke(ctx, mastStatus, 2.55, citron);
    ctx.globalAlpha = 1;

    const intensity = 0.62 + 0.37 * envelope(seconds, 2.58, 4.65, 15.55, 18.92);
    ctx.save();
    ctx.translate(0, rotorY);

    for (const lane of airflow) {
      stroke(ctx, lane.track.path, 1.85, "#275F55");
      const age = (seconds - lane.delay + 5) % 5;
      const u = age / 2.48;
      if (u >= 1) continue;
      const travel = 0.81 * u + 0.19 * ease(0, 1, u);
      const power = lane.gain * intensity * envelope(u, 0, 0.16, 0.72, 1);
      trail(ctx, lane.track, (lane.track.length + 29) * travel, 93, power, unit, 0.86);
    }

    const rotation = tau * (-0.30 + 2 * progress
      + 0.017 * (Math.sin(4 * tau * progress - gustPhase) + Math.sin(gustPhase))
      + 0.020 * Math.sin(tau * progress));
    for (let i = 0; i < 3; i++) {
      const angle = rotation + tau * i / 3;
      ctx.save();
      ctx.rotate(angle);
      ctx.fillStyle = "#14342D";
      ctx.fill(blade);
      ctx.shadowColor = "rgba(44,242,206,0.26)";
      ctx.shadowBlur = 8 * unit;
      stroke(ctx, blade, 3.65, "#4BA48E");
      ctx.shadowBlur = 0;
      stroke(ctx, blade, 1.15, "#9DE7D5");
      stroke(ctx, bladeLane.path, 1.9, "#427C72");

      const windward = (angle - 2.93 + 3 * tau) % tau;
      if (windward < 1.67) {
        const u = windward / 1.67;
        const travel = 0.75 * u + 0.25 * ease(0, 1, u);
        const power = intensity * envelope(windward, 0, 0.25, 1.23, 1.67);
        trail(ctx, bladeLane, (bladeLane.length + 24) * travel, 70, power, unit, 1);
      }
      ctx.restore();
    }

    ctx.fillStyle = "#15382F";
    ctx.fill(hub);
    stroke(ctx, hub, 3.0, "#73C9B3");
    stroke(ctx, hubInset, 1.55, "#478F80");
    ctx.fillStyle = "#A0E9C6";
    ctx.fill(hubCenter);
    ctx.rotate(rotation);
    stroke(ctx, hubTicks, 1.65, "#79C8B0");
    ctx.restore();
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(minSide / 1000, width / 1210);

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#071A1B";
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width * 0.5, height * 0.505);
  ctx.scale(unit, unit);
  paintWindHarmonics(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Ledger Rail. Time is in seconds and the scene loops every 20 seconds.
// UHD export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintLedgerRail = (() => {
  const duration = 20;
  const amber = "#FFC13D";
  const champagne = "#FFF0AA";
  const chipCenter = -239;
  const contactRows = [-78, 0, 78];
  const contactTimes = [4.72, 7.52, 10.34];

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function rounded(x, y, w, h, r) {
    const path = new Path2D();
    path.roundRect(x, y, w, h, r);
    return path;
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  const shell = rounded(-500, -292, 1000, 584, 52);
  const inset = rounded(-478, -270, 956, 540, 35);
  const header = new Path2D(
    "M -352 -229 H -268 M -251 -229 H -208 M -194 -229 H -174 " +
    "M 315 -229 H 337 M 350 -229 H 369 M 382 -229 H 397"
  );

  const chipFace = rounded(-362, -122, 246, 244, 24);
  const chipRim = new Path2D(
    "M -262 -122 H -338 Q -362 -122 -362 -98 V 98 Q -362 122 -338 122 H -262 " +
    "M -216 -122 H -140 Q -116 -122 -116 -98 V 98 Q -116 122 -140 122 H -216"
  );
  const verification = rounded(-63, -132, 435, 262, 22);

  const bands = contactRows.map((y, i) => {
    const contacts = [
      rounded(-339, y - 22, 83, 44, 8.5),
      rounded(-222, y - 22, 83, 44, 8.5)
    ];
    const traces = new Path2D(
      "M -325 " + y + " H -274 M -205 " + y + " H -153"
    );
    const latch = new Path2D("M 337 " + y + " H 349");
    const outputX = 300 - 120 * i;
    const output = new Path2D("M " + (outputX - 8) + " 151 H " + (outputX + 8));
    return {
      y, contacts, traces, latch, output,
      slot: rounded(-30, y - 19, 351, 38, 11),
      arrival: contactTimes[i],
      release: 14.22 + 1.12 * i
    };
  });

  // The continuous bus passes between the contacts and returns along the lower edge.
  const rail = new Path2D();
  rail.moveTo(-423, 61);
  const points = [{ x: -423, y: 61, length: 0 }];
  const marks = [];
  const spans = [
    [-423, -150], [-423, -183, -390, -183], [-274, -183], [chipCenter, -183, chipCenter, -149],
    [chipCenter, 140], [chipCenter, 176, -204, 176], [360, 176],
    [395, 176, 395, 206], [395, 236, 362, 236], [-388, 236], [-423, 236, -423, 198], [-423, 61]
  ];
  for (const span of spans) {
    const start = points[points.length - 1];
    const curve = span.length === 4;
    if (curve) rail.quadraticCurveTo(...span);
    else rail.lineTo(...span);

    const steps = curve ? 36 : 1;
    for (let i = 1; i <= steps; i++) {
      const u = i / steps;
      const v = 1 - u;
      const x = curve ? v * v * start.x + 2 * u * v * span[0] + u * u * span[2] : span[0];
      const y = curve ? v * v * start.y + 2 * u * v * span[1] + u * u * span[3] : span[1];
      const last = points[points.length - 1];
      points.push({ x, y, length: last.length + Math.hypot(x - last.x, y - last.y) });
    }
    marks.push(points[points.length - 1].length);
  }
  rail.closePath();

  const length = marks[marks.length - 1];
  const times = [0, ...contactTimes, 14.08, duration];
  const distances = [0, ...contactRows.map(y => marks[3] + y + 149), marks[6], length];
  const speeds = [155, 12, 11, 14, 125, 155];

  // Equal tangents at each waypoint keep the handoffs and seam smooth.
  function distanceAt(seconds) {
    let i = 0;
    while (seconds >= times[i + 1] && i < times.length - 2) i++;
    const span = times[i + 1] - times[i];
    const u = (seconds - times[i]) / span;
    const distance = distances[i + 1] - distances[i];
    const a = speeds[i] * span;
    const b = speeds[i + 1] * span;
    return distances[i] + u * (a + u * (3 * distance - 2 * a - b + u * (a + b - 2 * distance)));
  }

  function pointAt(distance) {
    let low = 0;
    let high = points.length - 1;
    while (high - low > 1) {
      const middle = (low + high) >>> 1;
      if (points[middle].length <= distance) low = middle;
      else high = middle;
    }
    const a = points[low];
    const b = points[high];
    const u = (distance - a.length) / (b.length - a.length);
    return { x: a.x + u * (b.x - a.x), y: a.y + u * (b.y - a.y), next: high };
  }

  function trail(ctx, head, tail, power, unit, weight) {
    const endDistance = (head + length) % length;
    const startDistance = (endDistance - tail + length) % length;
    const wraps = startDistance > endDistance;
    const start = pointAt(startDistance);
    const end = pointAt(endDistance);
    const path = new Path2D();
    path.moveTo(start.x, start.y);
    const stop = wraps ? points.length : end.next;
    for (let i = start.next; i < stop; i++) path.lineTo(points[i].x, points[i].y);
    if (wraps) {
      for (let i = 1; i < end.next; i++) path.lineTo(points[i].x, points[i].y);
    }
    path.lineTo(end.x, end.y);

    const tint = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    tint.addColorStop(0, "rgba(255,193,61,0)");
    tint.addColorStop(0.43, "rgba(255,193,61,0.25)");
    tint.addColorStop(0.82, amber);
    tint.addColorStop(1, champagne);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(255,240,170,0)");
    core.addColorStop(0.63, "rgba(255,240,170,0.45)");
    core.addColorStop(1, "#FFF9DE");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(255,185,63,0.79)";
    ctx.shadowBlur = 15 * unit * weight;
    stroke(ctx, path, 5.65 * weight, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.15 * weight, core);
    ctx.restore();
  }

  function indicator(ctx, path, power, unit) {
    stroke(ctx, path, 2.0, "#886431");
    if (power < 0.001) return;
    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(255,193,61,0.57)";
    ctx.shadowBlur = 8 * unit;
    stroke(ctx, path, 2.65, champagne);
    ctx.restore();
  }

  function paintBand(ctx, band, seconds, progress, i, unit) {
    const age = seconds - band.arrival;
    const contact = envelope(age, -0.39, 0.03, 0.39, 1.41);
    for (const pad of band.contacts) {
      ctx.fillStyle = "#3B2C15";
      ctx.fill(pad);
      stroke(ctx, pad, 1.8, "#8E682E");
      ctx.globalAlpha = 0.30 * contact;
      ctx.fillStyle = amber;
      ctx.fill(pad);
      ctx.globalAlpha = 1;
    }
    indicator(ctx, band.traces, 0.75 * contact, unit);

    ctx.fillStyle = "#21190D";
    ctx.fill(band.slot);
    stroke(ctx, band.slot, 1.8, "#765729");

    const filled = ease(0.32, 2.42, age);
    const released = ease(band.release, band.release + 2.21, seconds);
    const gain = 1 - released;
    const left = -22 + 334 * released;
    const right = -22 + 334 * filled;
    const width = right - left;
    if (width > 0.08) {
      ctx.save();
      ctx.globalAlpha = ease(0, 6, width);
      const body = rounded(left, band.y - 10.5, width, 21, Math.min(6, width * 0.5));
      const tint = ctx.createLinearGradient(left, band.y, right, band.y);
      tint.addColorStop(0, "#70491A");
      tint.addColorStop(0.66, "#B77824");
      tint.addColorStop(0.93, amber);
      tint.addColorStop(1, champagne);
      ctx.fillStyle = tint;
      ctx.fill(body);

      const phase = (4 * progress + 0.31 * i) % 1;
      const x = left - 28 + (width + 56) * phase;
      const sheen = ctx.createLinearGradient(x - 21, 0, x + 21, 0);
      sheen.addColorStop(0, "rgba(255,244,188,0)");
      sheen.addColorStop(0.5, "rgba(255,244,188,0.37)");
      sheen.addColorStop(1, "rgba(255,244,188,0)");
      ctx.fillStyle = sheen;
      ctx.fill(body);
      ctx.restore();
    }

    const confirmed = 0.70 * ease(2.20, 2.65, age) * gain;
    const sent = envelope(seconds, band.release + 0.19, band.release + 0.62,
      band.release + 0.96, band.release + 1.81);
    indicator(ctx, band.latch, confirmed, unit);
    indicator(ctx, band.output, sent, unit);
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#2C2011";
    ctx.fill(shell);
    ctx.shadowColor = "rgba(255,184,66,0.23)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, shell, 4.3, "#A87635");
    ctx.shadowBlur = 0;
    stroke(ctx, shell, 1.15, "#E8C17B");
    stroke(ctx, inset, 1.8, "#614923");
    stroke(ctx, header, 3.2, "#9A7439");

    ctx.fillStyle = "#322510";
    ctx.fill(chipFace);
    stroke(ctx, chipRim, 2.6, "#AE853F");

    ctx.fillStyle = "#251B0E";
    ctx.fill(verification);
    stroke(ctx, verification, 1.8, "#6C5027");

    stroke(ctx, rail, 2.0, "#866230");
    for (let i = 0; i < bands.length; i++) paintBand(ctx, bands[i], seconds, progress, i, unit);

    const head = distanceAt(seconds);
    trail(ctx, head - 126, 45, 0.38, unit, 0.66);
    trail(ctx, head, 95, 1, unit, 1);
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(minSide / 1000, width / 1150);

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
