  ctx.scale(unit, unit);
  paintLedgerRail(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Route Pin. Time is in seconds and the scene loops every 20 seconds.
// UHD export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintRoutePin = (() => {
  const tau = 2 * Math.PI;
  const indigo = "#626BFF";
  const periwinkle = "#BFC8FF";
  const targetY = 126;

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  // Store arc length so each packet follows the same centerline as its rail.
  function rail(x, y, spans) {
    const path = new Path2D();
    path.moveTo(x, y);
    const points = [{ x, y, length: 0 }];
    const marks = [];

    for (const span of spans) {
      const start = points[points.length - 1];
      if (span.length === 2) path.lineTo(...span);
      if (span.length === 4) path.quadraticCurveTo(...span);
      if (span.length === 6) path.bezierCurveTo(...span);

      const count = span.length === 2 ? 1 : 64;
      for (let i = 1; i <= count; i++) {
        const u = i / count;
        const v = 1 - u;
        let x = span[0];
        let y = span[1];
        if (span.length === 4) {
          x = v * v * start.x + 2 * v * u * span[0] + u * u * span[2];
          y = v * v * start.y + 2 * v * u * span[1] + u * u * span[3];
        }
        if (span.length === 6) {
          x = v ** 3 * start.x + 3 * v * v * u * span[0] + 3 * v * u * u * span[2] + u ** 3 * span[4];
          y = v ** 3 * start.y + 3 * v * v * u * span[1] + 3 * v * u * u * span[3] + u ** 3 * span[5];
        }
        const last = points[points.length - 1];
        points.push({ x, y, length: last.length + Math.hypot(x - last.x, y - last.y) });
      }
      marks.push(points[points.length - 1].length);
    }
    return { path, points, marks, length: marks[marks.length - 1] };
  }

  const border = rail(0, -312, [
    [-142, -312, -248, -213, -248, -76],
    [-248, 90, -121, 220, -29, 310],
    [-13, 327, 0, 327], [13, 327, 29, 310],
    [121, 220, 248, 90, 248, -76],
    [248, -213, 142, -312, 0, -312]
  ]);
  border.path.closePath();

  const route = rail(-132, -193, [
    [67, -193], [101, -193, 128, -167, 128, -132], [128, -98, 101, -71, 67, -71],
    [-64, -71], [-98, -71, -122, -46, -122, -12], [-122, 21, -98, 48, -64, 48],
    [-29, 48], [-13, 48, 0, 60, 0, 76], [0, 96]
  ]);
  const returnRail = rail(14, 286, [
    [92, 204, 215, 69, 215, -76],
    [215, -195, 124, -278, 0, -278],
    [-87, -278, -151, -238, -184, -179]
  ]);

  const routeTimes = [0.35, 2.33, 4.93, 6.47, 9.04, 10.66];
  const routeMarks = [0, route.marks[0], route.marks[2], route.marks[3], route.marks[5], route.length];
  const routeSpeeds = [0, 56, 53, 56, 49, 0];

  function routeDistance(seconds) {
    if (seconds <= routeTimes[0]) return 0;
    if (seconds >= routeTimes[routeTimes.length - 1]) return route.length;

    let i = 0;
    while (seconds >= routeTimes[i + 1]) i++;
    const span = routeTimes[i + 1] - routeTimes[i];
    const u = (seconds - routeTimes[i]) / span;
    const distance = routeMarks[i + 1] - routeMarks[i];
    const a = routeSpeeds[i] * span;
    const b = routeSpeeds[i + 1] * span;
    return routeMarks[i] + u * (a + u * (3 * distance - 2 * a - b + u * (a + b - 2 * distance)));
  }

  function pointAt(points, distance) {
    let low = 0;
    let high = points.length - 1;
    while (high - low > 1) {
      const middle = (low + high) >>> 1;
      if (points[middle].length <= distance) low = middle;
      else high = middle;
    }
    const a = points[low];
    const b = points[high];
    const u = (distance - a.length) / (b.length - a.length);
    return { x: a.x + u * (b.x - a.x), y: a.y + u * (b.y - a.y), next: high };
  }

  function trail(ctx, track, head, tail, power, unit, weight, closed) {
    if (power < 0.001) return;
    const length = track.length;
    const to = closed ? (head + length) % length : Math.min(head, length);
    const from = closed ? (to - tail + length) % length : Math.max(0, head - tail);
    if (!closed && to - from < 0.12) return;

    const points = track.points;
    const wraps = from > to;
    const start = pointAt(points, from);
    const end = pointAt(points, to);
    const path = new Path2D();
    path.moveTo(start.x, start.y);
    const stop = wraps ? points.length : end.next;
    for (let i = start.next; i < stop; i++) path.lineTo(points[i].x, points[i].y);
    if (wraps) {
      for (let i = 1; i < end.next; i++) path.lineTo(points[i].x, points[i].y);
    }
    path.lineTo(end.x, end.y);

    const tint = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    tint.addColorStop(0, "rgba(98,107,255,0)");
    tint.addColorStop(0.39, "rgba(98,107,255,0.30)");
    tint.addColorStop(0.80, indigo);
    tint.addColorStop(1, periwinkle);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(191,200,255,0)");
    core.addColorStop(0.59, "rgba(191,200,255,0.38)");
    core.addColorStop(1, "#F1F3FF");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(106,112,255,0.83)";
    ctx.shadowBlur = 16 * unit * weight;
    stroke(ctx, path, 5.65 * weight, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.15 * weight, core);
    ctx.restore();
    return end;
  }

  const entry = new Path2D();
  entry.arc(-151, -193, 5.3, 0, tau);
  const target = new Path2D();
  target.arc(0, targetY, 10.8, 0, tau);
  const targetCore = new Path2D();
  targetCore.arc(0, targetY, 3.35, 0, tau);

  const coordinates = new Path2D();
  for (const side of [-1, 1]) {
    for (let i = 0; i < 6; i++) {
      const y = -129 + 26 * i;
      coordinates.moveTo(side * 172, y);
      coordinates.lineTo(side * (i % 3 === 0 ? 184 : 179), y);
    }
  }
  const relays = [177, 207, 237, 262].map((y, i) => {
    const x = 5.5 + 1.25 * i;
    return new Path2D("M " + -x + " " + y + " H " + x);
  });

  function indicator(ctx, path, power, unit) {
    stroke(ctx, path, 1.95, "#4954A0");
    if (power < 0.001) return;
    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(98,107,255,0.61)";
    ctx.shadowBlur = 8 * unit;
    stroke(ctx, path, 2.5, periwinkle);
    ctx.restore();
  }

  // The vertical gaps keep each echo clear of the incoming and outgoing lanes.
  function echo(ctx, age, unit, weight) {
    const span = 2.38;
    if (age <= 0 || age >= span) return;
    const u = age / span;
    const radius = 16 + 44 * (0.82 * u + 0.18 * ease(0, 1, u));
    const power = weight * envelope(u, 0, 0.18, 0.56, 1);
    const arcAngle = 0.98;
    const path = new Path2D();
    path.arc(0, targetY, radius, -arcAngle, arcAngle);
    path.moveTo(radius * Math.cos(Math.PI - arcAngle), targetY + radius * Math.sin(Math.PI - arcAngle));
    path.arc(0, targetY, radius, Math.PI - arcAngle, Math.PI + arcAngle);

    const reach = radius * Math.sin(arcAngle);
    const tint = ctx.createLinearGradient(0, targetY - reach, 0, targetY + reach);
    tint.addColorStop(0, "rgba(98,107,255,0)");
    tint.addColorStop(0.24, indigo);
    tint.addColorStop(0.5, periwinkle);
    tint.addColorStop(0.76, indigo);
    tint.addColorStop(1, "rgba(98,107,255,0)");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(98,107,255,0.62)";
    ctx.shadowBlur = 7 * unit;
    stroke(ctx, path, 2.45 - 1.04 * u, tint);
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#11183A";
    ctx.fill(border.path);
    ctx.shadowColor = "rgba(98,107,255,0.28)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, border.path, 4.2, "#6670CF");
    ctx.shadowBlur = 0;
    stroke(ctx, border.path, 1.25, "#A9B4F5");

    stroke(ctx, returnRail.path, 2.0, "#39468C");
    stroke(ctx, route.path, 2.65, "#5260B1");
    stroke(ctx, coordinates, 1.7, "#454D91");

    const entryAge = (seconds + 0.44) % 20;
    indicator(ctx, entry, 0.85 * envelope(entryAge, 0, 0.31, 0.55, 1.15), unit);
    for (let i = 0; i < relays.length; i++) {
      const age = seconds - (12.22 + 0.27 * i);
      indicator(ctx, relays[i], 0.84 * envelope(age, 0, 0.22, 0.35, 0.77), unit);
    }

    const outlineHead = (2 * progress + 0.12) % 1 * border.length;
    trail(ctx, border, outlineHead, 118, 0.49, unit, 0.72, true);

    const routePower = envelope(seconds, 0.35, 0.91, 10.62, 11.15);
    const point = trail(ctx, route, routeDistance(seconds), 80, routePower, unit, 1, false);
    if (point) {
      const head = new Path2D();
      head.arc(point.x, point.y, 3.7, 0, tau);
      ctx.save();
      ctx.globalAlpha = routePower;
      ctx.fillStyle = "#E9EEFF";
      ctx.fill(head);
      ctx.restore();
    }

    const returnPhase = Math.max(0, Math.min(1, (seconds - 13.04) / 6.78));
    const returnHead = (0.78 * returnPhase + 0.22 * ease(0, 1, returnPhase)) * (returnRail.length + 36);
    const returnPower = envelope(seconds, 13.04, 13.63, 19.28, 19.82);
    trail(ctx, returnRail, returnHead, 105, returnPower, unit, 0.92, false);

    const arrived = envelope(seconds, 10.48, 10.96, 12.22, 13.34);
    indicator(ctx, target, arrived, unit);
    ctx.save();
    ctx.globalAlpha = 0.36 + 0.64 * arrived;
    ctx.fillStyle = periwinkle;
    ctx.fill(targetCore);
    ctx.restore();
    echo(ctx, seconds - 10.77, unit, 0.91);
    echo(ctx, seconds - 11.55, unit, 0.70);
  };
})();

