    scale.lineTo(x * outer, y * outer);
    ticks.push({ angle, path });
  }

  // The slices live inside the sweep lane and keep their shape during reconstruction.
  const slices = [61, 83, 102, 112, 102, 83, 61].map((width, i) => {
    const y = (i - 3) * 29;
    const path = new Path2D();
    path.moveTo(-width, y);
    path.quadraticCurveTo(-width + 17, y - 8, -width + 37, y - 8);
    path.lineTo(width - 37, y - 8);
    path.quadraticCurveTo(width - 17, y - 8, width, y);
    path.quadraticCurveTo(width - 17, y + 8, width - 37, y + 8);
    path.lineTo(-width + 37, y + 8);
    path.quadraticCurveTo(-width + 17, y + 8, -width, y);
    path.closePath();

    const profile = new Path2D();
    profile.moveTo(-0.55 * width, y);
    profile.lineTo(-0.13 * width, y);
    profile.moveTo(0.02 * width, y);
    profile.lineTo(0.55 * width, y);
    return { path, profile, angle: Math.asin(y / 154), fadeAt: 14.17 + i * 0.53 };
  });

  function rimLight(ctx, angle, tail, power, unit) {
    const from = angle - tail;
    const path = new Path2D();
    path.arc(0, 0, ringRadius, from, angle);
    const color = ctx.createLinearGradient(
      ringRadius * Math.cos(from), ringRadius * Math.sin(from),
      ringRadius * Math.cos(angle), ringRadius * Math.sin(angle)
    );
    color.addColorStop(0, "rgba(250,75,135,0)");
    color.addColorStop(0.43, "rgba(250,75,135,0.36)");
    color.addColorStop(0.78, ruby);
    color.addColorStop(1, rose);

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(250,75,135,0.84)";
    ctx.shadowBlur = 17 * unit;
    stroke(ctx, path, 5.1, color);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.25, color);
    ctx.restore();
  }

  function paintFan(ctx, angle, power, unit) {
    if (power < 0.001) return;
    const from = angle - 0.58;
    const mid = (fanInner + fanOuter) * 0.5;
    const sector = new Path2D();
    sector.arc(0, 0, fanOuter, from, angle);
    sector.arc(0, 0, fanInner, angle, from, true);
    sector.closePath();

    const tint = ctx.createLinearGradient(mid * Math.cos(from), mid * Math.sin(from),
      mid * Math.cos(angle), mid * Math.sin(angle));
    tint.addColorStop(0, "rgba(250,75,135,0)");
    tint.addColorStop(0.37, "rgba(250,75,135,0.08)");
    tint.addColorStop(0.79, "rgba(250,75,135,0.25)");
    tint.addColorStop(1, "rgba(250,75,135,0.47)");

    const tip = new Path2D();
    tip.moveTo((fanInner + 3) * Math.cos(angle), (fanInner + 3) * Math.sin(angle));
    tip.lineTo((fanOuter - 3) * Math.cos(angle), (fanOuter - 3) * Math.sin(angle));

    ctx.save();
    ctx.globalAlpha = power;
    ctx.fillStyle = tint;
    ctx.fill(sector);
    ctx.shadowColor = "rgba(250,75,135,0.73)";
    ctx.shadowBlur = 8 * unit;
    stroke(ctx, tip, 2.8, rose);
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#2A1324";
    ctx.fill(housing);
    ctx.shadowColor = "rgba(250,75,135,0.22)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, housing, 4.25, "#A54D72");
    ctx.shadowBlur = 0;
    stroke(ctx, housing, 1.1, "#DE88A9");
    stroke(ctx, inset, 1.8, "#64344D");

    ctx.fillStyle = "#211021";
    ctx.fill(ventBorder);
    stroke(ctx, ventBorder, 1.65, "#67334E");
    stroke(ctx, ribs, 2.2, "#8B4364");

    const fanPower = envelope(seconds, 4.95, 5.82, 13.02, 14.06);
    for (const path of sideLights) {
      stroke(ctx, path, 2.25, "#7E3B57");
      ctx.globalAlpha = 0.15 + 0.62 * fanPower;
      stroke(ctx, path, 2.7, rose);
      ctx.globalAlpha = 1;
    }

    ctx.fillStyle = "#1C101E";
    ctx.fill(tray);
    stroke(ctx, tray, 1.95, "#7C4561");
    stroke(ctx, trayTrim, 1.7, "#A85C7D");

    ctx.save();
    ctx.translate(0, -21);
    ctx.fillStyle = "#170E1A";
    ctx.fill(glass);
    stroke(ctx, glass, 2.6, "#82405F");
    stroke(ctx, insetRing, 1.55, "#613047");
    stroke(ctx, rim, 3.1, "#A65274");
    stroke(ctx, scale, 1.7, "#87405F");

    const calibration = -Math.PI * 0.5 + tau * (2 * progress + 0.085 * Math.sin(tau * progress));
    const calibrationPower = 0.60 + 0.32 * (1 - fanPower);
    rimLight(ctx, calibration + Math.PI, 0.40, 0.48 * calibrationPower, unit);
    rimLight(ctx, calibration, 0.62, calibrationPower, unit);

    for (const tick of ticks) {
      const lag = (calibration - tick.angle + 3 * tau) % tau;
      const power = envelope(lag, 0, 0.10, 0.18, 0.55) * calibrationPower;
      if (power < 0.001) continue;
      ctx.globalAlpha = power;
      stroke(ctx, tick.path, 2.45, rose);
      ctx.globalAlpha = 1;
    }

    const scanAngle = scanBegin + (scanFinish - scanBegin) * ease(4.95, 14.05, seconds);
    for (const slice of slices) {
      stroke(ctx, slice.path, 1.25, "#3B1C33");
      const formed = ease(slice.angle - 0.11, slice.angle + 0.08, scanAngle);
      const persistence = 1 - ease(slice.fadeAt, slice.fadeAt + 1.92, seconds);
      const power = formed * persistence;
      if (power < 0.001) continue;

      const flash = envelope(scanAngle, slice.angle - 0.11, slice.angle + 0.02,
        slice.angle + 0.10, slice.angle + 0.28);
      ctx.save();
      ctx.globalAlpha = power;
      ctx.fillStyle = "#58213E";
      ctx.fill(slice.path);
      ctx.shadowColor = "rgba(250,75,135,0.57)";
      ctx.shadowBlur = 5.2 * unit;
      stroke(ctx, slice.path, 1.9, "#C35A85");
      ctx.shadowBlur = 0;
      ctx.globalAlpha = power * flash;
      stroke(ctx, slice.path, 1.9, ruby);
      ctx.globalAlpha = power * (0.42 + 0.54 * flash);
      stroke(ctx, slice.profile, 1.6, rose);
      ctx.restore();
    }

    paintFan(ctx, scanAngle, fanPower, unit);
    ctx.restore();
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(minSide / 1000, width / 800);

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#1D0C1B";
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width * 0.5, height * 0.505);
  ctx.scale(unit, unit);
  paintClinicalSlice(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Stereo Phase. Time is in seconds and the scene loops every 20 seconds.
// UHD export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintStereoPhase = (() => {
  const tau = 2 * Math.PI;
  const emerald = "#25DF94";
  const mint = "#A4FFCC";
  const halfWidth = 410;
  const laneCenter = 81;

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  const shell = new Path2D();
  shell.roundRect(-535, -216, 1070, 432, 128);

  const inset = new Path2D();
  inset.roundRect(-508, -187, 1016, 374, 106);

  const lanes = new Path2D();
  lanes.roundRect(-437, -144, 874, 126, 31);
  lanes.roundRect(-437, 18, 874, 126, 31);

  const scale = new Path2D();
  for (const side of [-1, 1]) {
    for (let i = -11; i <= 11; i++) {
      const x = 33 * i;
      scale.moveTo(x, side * 198);
      scale.lineTo(x, side * (i % 3 === 0 ? 206 : 203));
    }
  }

  const meters = new Path2D();
  for (const side of [-1, 1]) {
    for (const center of [-laneCenter, laneCenter]) {
      for (let i = -2; i <= 2; i++) {
        const y = center + 13 * i;
        meters.moveTo(side * 464, y);
        meters.lineTo(side * (i === 0 ? 484 : 473), y);
      }
    }
  }

  const divider = new Path2D("M -407 0 H -30 M 30 0 H 407");
  const sync = new Path2D("M 0 -6 L 8 0 L 0 6 L -8 0 Z");
  const echoRails = new Path2D("M -398 -166 H -24 M 24 -166 H 398 M -398 166 H -24 M 24 166 H 398");

  // The wave travels inside a fixed lane. Its packet fades outside the visible span.
  function drawWave(ctx, direction, progress, offset, gain, unit) {
    const phase = (4 * progress + direction * offset + 1) % 1;
    const packet = -0.24 + 1.48 * (0.88 * phase + 0.12 * ease(0, 1, phase));
    const center = -direction * laneCenter;
    const path = new Path2D();

    let previousX = -halfWidth;
    let previousY = center;
    path.moveTo(previousX, previousY);
    const steps = 192;
    for (let i = 1; i <= steps; i++) {
      const xProgress = i / steps;
      const travel = direction === 1 ? xProgress : 1 - xProgress;
      const x = -halfWidth + 2 * halfWidth * xProgress;
      const ends = envelope(travel, 0, 0.105, 0.895, 1);
      const focus = 1 - ease(0.027, 0.226, Math.abs(travel - packet));
      const amplitude = (16 + 31 * focus) * gain * ends;
      const carrier = tau * (2.9 * travel - 16 * progress - 1.20);
      const form = 0.77 * Math.sin(carrier)
        + 0.17 * Math.sin(2 * carrier - 0.72)
        + 0.06 * Math.sin(3 * carrier + 0.80);
      const y = center + direction * amplitude * form;
      path.quadraticCurveTo(previousX, previousY, (previousX + x) * 0.5, (previousY + y) * 0.5);
      previousX = x;
      previousY = y;
    }
    path.lineTo(previousX, previousY);

    const centerX = direction * (2 * packet - 1) * halfWidth;
    const tint = ctx.createLinearGradient(centerX - 128, 0, centerX + 128, 0);
    tint.addColorStop(0, "rgba(37,223,148,0)");
    tint.addColorStop(0.23, "rgba(37,223,148,0.26)");
    tint.addColorStop(0.5, mint);
    tint.addColorStop(0.77, "rgba(37,223,148,0.26)");
    tint.addColorStop(1, "rgba(37,223,148,0)");

    ctx.save();
    ctx.shadowColor = "rgba(37,223,148,0.32)";
    ctx.shadowBlur = 8 * unit;
    stroke(ctx, path, 3.25, direction === 1 ? "#45BC8D" : "#3CAD82");
    ctx.shadowColor = "rgba(37,223,148,0.80)";
    ctx.shadowBlur = 14 * unit;
    stroke(ctx, path, 5.3, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.0, tint);
    ctx.restore();
  }

  function paintEcho(ctx, y, age, level, unit) {
    const power = level * envelope(age, 0, 0.31, 1.45, 2.12);
    if (power < 0.001) return;
    const head = 22 + 426 * ease(0, 2.10, age);
    const from = Math.max(24, head - 97);
    const to = Math.min(398, head);
    if (to - from < 0.1) return;

    for (const side of [-1, 1]) {
      const path = new Path2D();
      path.moveTo(side * from, y);
      path.lineTo(side * to, y);
      const tint = ctx.createLinearGradient(side * from, y, side * to, y);
      tint.addColorStop(0, "rgba(37,223,148,0)");
      tint.addColorStop(0.44, "rgba(37,223,148,0.26)");
      tint.addColorStop(0.83, emerald);
      tint.addColorStop(1, mint);

      ctx.save();
      ctx.globalAlpha = power;
      ctx.shadowColor = "rgba(37,223,148,0.66)";
      ctx.shadowBlur = 9 * unit;
      stroke(ctx, path, 3.8, tint);
      ctx.shadowBlur = 0;
      stroke(ctx, path, 1.7, tint);
      ctx.restore();
    }
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#10271F";
    ctx.fill(shell);
    ctx.shadowColor = "rgba(37,223,148,0.23)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, shell, 4.35, "#438F71");
    ctx.shadowBlur = 0;
    stroke(ctx, shell, 1.25, "#8BD7B6");
    stroke(ctx, inset, 1.85, "#2B5C4A");
    stroke(ctx, scale, 1.65, "#427D67");

    ctx.fillStyle = "#0C2019";
    ctx.fill(lanes);
    stroke(ctx, lanes, 1.85, "#295642");
    stroke(ctx, meters, 1.8, "#508C75");
    stroke(ctx, divider, 1.5, "#2D644E");
    stroke(ctx, echoRails, 1.5, "#295E49");

    const gain = 0.52 + 0.43 * envelope(seconds, 0, 5.4, 14.8, 20);
    const offset = 0.035 * Math.sin(2 * tau * progress);
    drawWave(ctx, 1, progress, offset, gain, unit);
    drawWave(ctx, -1, progress, offset, gain, unit);

    const echoAge = (seconds + 2.5) % 5;
    const echoPower = 0.42 + 0.57 * gain;
    paintEcho(ctx, -166, echoAge, echoPower, unit);
    paintEcho(ctx, 166, (echoAge + 4.87) % 5, echoPower * 0.82, unit);

    ctx.fillStyle = "#275544";
    ctx.fill(sync);
    stroke(ctx, sync, 1.65, "#66A68B");
    const syncPower = echoPower * envelope(echoAge, 0, 0.17, 0.31, 0.73);
    ctx.save();
    ctx.globalAlpha = syncPower;
    ctx.shadowColor = "rgba(37,223,148,0.68)";
    ctx.shadowBlur = 8 * unit;
    stroke(ctx, sync, 2.1, mint);
    ctx.restore();
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;
  const minSide = Math.min(width, height);
  const unit = Math.min(minSide / 1000, width / 1240);

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#081A15";
  ctx.fillRect(0, 0, width, height);
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(unit, unit);
  paintStereoPhase(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Orbital Uplink. The timeline uses seconds and repeats every 20 seconds.
// 4K export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintOrbitalUplink = (() => {
  const duration = 20;
  const amethyst = "#9C58FF";
  const lilac = "#E1BEFF";
  const angle = -Math.PI / 5;
  const originX = -72;
  const originY = -24;
  const pivotX = originX - 187 * Math.cos(angle);
  const pivotY = originY - 187 * Math.sin(angle);
  const waveX = 83;

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function since(seconds, start) {
    return (seconds - start + duration) % duration;
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  // Cache the rails and their arc lengths so highlights round bends at a steady speed.
  function rail(x, y, spans) {
    const path = new Path2D();
    path.moveTo(x, y);
    const samples = [{ x, y, length: 0 }];
    for (const span of spans) {
      const start = samples[samples.length - 1];
      const isCurve = span.length === 4;
      if (isCurve) path.quadraticCurveTo(...span);
      else path.lineTo(...span);

      const count = isCurve ? 64 : 1;
      for (let i = 1; i <= count; i++) {
        const u = i / count;
        const v = 1 - u;
        const nextX = isCurve ? v * v * start.x + 2 * u * v * span[0] + u * u * span[2] : span[0];
        const nextY = isCurve ? v * v * start.y + 2 * u * v * span[1] + u * u * span[3] : span[1];
        const last = samples[samples.length - 1];
        samples.push({ x: nextX, y: nextY, length: last.length + Math.hypot(nextX - last.x, nextY - last.y) });
      }
    }
    return { path, samples, length: samples[samples.length - 1].length };
  }

  function pointAt(track, distance) {
    let low = 0;
    let high = track.samples.length - 1;
    while (high - low > 1) {
      const middle = (low + high) >>> 1;
      if (track.samples[middle].length <= distance) low = middle;
      else high = middle;
    }
    const a = track.samples[low];
    const b = track.samples[high];
    const u = (distance - a.length) / (b.length - a.length);
    return { x: a.x + u * (b.x - a.x), y: a.y + u * (b.y - a.y), next: high };
  }

  function trail(ctx, track, head, tail, power, unit, weight) {
    const from = Math.max(0, head - tail);
    const to = Math.min(head, track.length);
    if (power < 0.001 || to - from < 0.15) return;

    const start = pointAt(track, from);
    const end = pointAt(track, to);
    const path = new Path2D();
    path.moveTo(start.x, start.y);
    for (let i = start.next; i < end.next; i++) {
      const point = track.samples[i];
      path.lineTo(point.x, point.y);
    }
    path.lineTo(end.x, end.y);

    const color = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    color.addColorStop(0, "rgba(156,88,255,0)");
    color.addColorStop(0.37, "rgba(156,88,255,0.25)");
    color.addColorStop(0.81, amethyst);
    color.addColorStop(1, lilac);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(225,190,255,0)");
    core.addColorStop(0.56, "rgba(225,190,255,0.32)");
    core.addColorStop(1, "#FCEDFF");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(171,96,255,0.9)";
    ctx.shadowBlur = 20 * unit * weight;
    stroke(ctx, path, 6.1 * weight, color);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.5 * weight, core);
    ctx.restore();
  }

  function pass(ctx, track, age, span, tail, unit) {
    if (age >= span) return;
    const u = age / span;
    const distance = (0.74 * u + 0.26 * ease(0, 1, u)) * (track.length + 0.4 * tail);
    trail(ctx, track, distance, tail, envelope(u, 0, 0.14, 0.84, 1), unit, 1);
  }

  const support = new Path2D(
    "M -13 22 Q 0 29 14 22 L 35 130 Q 38 145 55 145 H 70 Q 87 145 87 160 " +
    "V 168 Q 87 177 76 177 H -71 Q -83 177 -83 168 V 160 Q -83 145 -65 145 " +
    "H -22 Q -5 145 -6 129 Z"
  );
  const supportRail = rail(-62, 161, [[7, 161], [23, 161, 20, 143], [2, 36]]);
  const hinge = new Path2D();
  hinge.arc(0, 0, 10.5, 0, 2 * Math.PI);
  const hingePin = new Path2D();
  hingePin.arc(0, 0, 3.5, 0, 2 * Math.PI);

  const scaleArc = new Path2D();
  scaleArc.arc(0, 0, 37, 2.16, 3.24);
  const scaleTicks = new Path2D();
  for (let i = 0; i < 7; i++) {
    const a = 2.16 + 0.18 * i;
    const outer = i % 3 === 0 ? 53 : 48;
    scaleTicks.moveTo(43 * Math.cos(a), 43 * Math.sin(a));
    scaleTicks.lineTo(outer * Math.cos(a), outer * Math.sin(a));
  }

  const dish = new Path2D(
    "M -1 -178 Q -328 0 -1 178 Q 8 182 10 171 Q -281 0 10 -171 Q 8 -182 -1 -178 Z"
  );
  const back = new Path2D("M -1 -178 Q -328 0 -1 178");
  const rib = new Path2D("M -48 -143 Q -250 0 -48 143");
  const rim = rail(10, -171, [[-281, 0, 10, 171]]);

  const arm = new Path2D();
  arm.roundRect(-116, -8, 145, 16, 8);
  const armRail = rail(-105, 0, [[18, 0]]);
  const emitter = new Path2D(
    "M 42 -9 L 60 -19 H 72 Q 78 -19 78 -13 V 13 Q 78 19 72 19 H 60 L 42 9 Z"
  );
  const aperture = new Path2D("M 67 -10 V 10");

  const launches = [4.84, 6.36, 7.88, 9.4, 10.92, 12.44];
  const replies = [14.87, 16.58];

  function wave(ctx, age, incoming, unit) {
    const span = incoming ? 3.27 : 4.16;
    if (age <= 0 || age >= span) return;

    const u = age / span;
    const travel = 0.83 * u + 0.17 * ease(0, 1, u);
    const radius = incoming ? 327 - 282 * travel : 43 + 298 * travel;
    const opening = ease(0, 1, incoming ? 1 - u : u);
    const from = incoming ? 0.79 - 0.035 * opening : -0.42 - 0.15 * opening;
    const to = incoming ? 1.09 + 0.035 * opening : 0.46 + 0.15 * opening;
    const weight = incoming ? 1.55 + 0.7 * u : 3.45 - 2 * u;
    const power = envelope(u, 0, 0.13, 0.68, 1) * (incoming ? 0.72 : 1 - 0.23 * u);

    const arc = new Path2D();
    arc.arc(waveX, 0, radius, from, to);
    const endY0 = radius * Math.sin(from);
    const endY1 = radius * Math.sin(to);
    const beam = ctx.createLinearGradient(0, endY0, 0, endY1);
    beam.addColorStop(0, "rgba(156,88,255,0)");
    beam.addColorStop(0.18, incoming ? "#B983E9" : amethyst);
    beam.addColorStop(0.53, lilac);
    beam.addColorStop(0.84, amethyst);
    beam.addColorStop(1, "rgba(156,88,255,0)");

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(166,96,255,0.84)";
    ctx.shadowBlur = (incoming ? 12 : 19) * unit;
    stroke(ctx, arc, weight + 1.8, beam);
    ctx.shadowBlur = 0;
    stroke(ctx, arc, weight, beam);

    const middle = from + (to - from) * (0.31 + 0.37 * opening);
    const spread = (to - from) * 0.10;
    const glint = new Path2D();
    glint.arc(waveX, 0, radius, middle - spread, middle + spread);
