    ctx.translate(pivotX, pivotY);
    ctx.fillStyle = "#1D1330";
    ctx.fill(support);
    stroke(ctx, support, 3.4, "#7950A9");
    stroke(ctx, supportRail.path, 2.15, "#68448F");
    stroke(ctx, scaleArc, 1.7, "#5F437E");
    stroke(ctx, scaleTicks, 1.6, "#785393");
    ctx.fillStyle = "#25173D";
    ctx.fill(hinge);
