    ctx.fillStyle = "#261639";
    ctx.fill(dish);
    stroke(ctx, back, 2.5, "#73519F");
    stroke(ctx, rib, 1.5, "#8354AE");

    ctx.shadowColor = "rgba(156,88,255,0.38)";
    ctx.shadowBlur = 9 * unit;
