    ctx.fillStyle = "#301A47";
    ctx.fill(emitter);
    stroke(ctx, emitter, 2.55, "#AC7BD3");
    stroke(ctx, aperture, 2.25, "#8A60AB");
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(189,126,255,0.88)";
    ctx.shadowBlur = 13 * unit;
    stroke(ctx, aperture, 3.6, lilac);
    ctx.restore();
