// Freight Trace. The timeline uses seconds and repeats every 20 seconds.
// 4K export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintFreightTrace = (() => {
  const duration = 20;
  const copper = "#E98D53";
  const cream = "#FFD4A6";
  const scanStart = 3.95;
  const scanEnd = 11.90;
  const entryX = -347;
  const scanLeft = -206;
  const scanRight = 352;
  const returnStart = 14.48;
  const scanSpeed = (scanRight - scanLeft) / (scanEnd - scanStart);
  const seamSpeed = 130;
  const returnSpeed = 127;

  function ease(from, to, value) {
    const u = Math.max(0, Math.min(1, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, start, full, release, end) {
    return ease(start, full, value) * (1 - ease(release, end, value));
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  const shell = new Path2D(
    "M -478 -63 L -353 -188 Q -344 -197 -327 -197 H 449 Q 494 -197 494 -152 " +
    "V 152 Q 494 197 449 197 H -327 Q -344 197 -353 188 L -478 63 " +
    "Q -493 48 -493 26 V -26 Q -493 -48 -478 -63 Z"
