  punchBezel.moveTo(-346 + 39 * Math.cos(0.49), 39 * Math.sin(0.49));
  punchBezel.arc(-346, 0, 39, 0.49, 2.65);

  const perforation = new Path2D();
  for (let y = -83; y <= 83; y += 16.6) {
    perforation.moveTo(-251, y - 2.8);
    perforation.lineTo(-251, y + 2.8);
  }

  const header = new Path2D(
    "M -189 -150 H -130 M -117 -150 H -89 M -75 -150 H -50 " +
    "M 274 -150 H 298 M 309 -150 H 332 M 343 -150 H 357"
  );
  const scanner = new Path2D("M -22 92 H 13 M 20 92 H 26");

  // The continuous rail carries the scan signal and then the return packet.
  const rail = new Path2D();
  rail.moveTo(-297, 144);
  const points = [{ x: -297, y: 144, length: 0 }];
  const marks = [];
  const spans = [
    [-315, 144], [-336, 144, -351, 129], [-417, 63], [-433, 47, -433, 29],
    [-433, -32], [-433, -49, -417, -65], [-383, -99], [-368, -114, entryX, -114],
    [373, -114], [405, -114, 405, -82], [405, 117], [405, 144, 378, 144], [-297, 144]
  ];

  for (const span of spans) {
    const start = points[points.length - 1];
    const curve = span.length === 4;
    if (curve) rail.quadraticCurveTo(...span);
    else rail.lineTo(...span);

    const steps = curve ? 32 : 1;
    for (let i = 1; i <= steps; i++) {
      const u = i / steps;
      const v = 1 - u;
      const x = curve ? v * v * start.x + 2 * v * u * span[0] + u * u * span[2] : span[0];
      const y = curve ? v * v * start.y + 2 * v * u * span[1] + u * u * span[3] : span[1];
      const last = points[points.length - 1];
      points.push({ x, y, length: last.length + Math.hypot(x - last.x, y - last.y) });
    }
    marks.push(points[points.length - 1].length);
