  rail.closePath();

  const railLength = marks[marks.length - 1];
  const scanMark = marks[7] + scanLeft - entryX;
  const exitMark = scanMark + scanRight - scanLeft;
  const returnMark = marks[11];

  const patterns = [
    [8, 14, 7, 11, 6, 10],
    [13, 6, 9, 12, 7, 8],
    [7, 10, 14, 6, 11, 7],
    [10, 6, 12, 8, 14, 6],
    [7, 13, 6, 9, 7, 15]
  ];
  const bars = [];
  const barField = new Path2D();
  const groups = [];

  for (let group = 0; group < patterns.length; group++) {
    const firstX = -190 + 110 * group;
    let x = firstX;
    for (let i = 0; i < patterns[group].length; i++) {
      const width = patterns[group][i];
      const top = -71 + 3 * ((2 * i + group) % 3);
