    register.moveTo(center - 15, 114);
    register.lineTo(center - 8, 114);
    register.moveTo(center - 3, 114);
    register.lineTo(center + 3, 114);
    register.moveTo(center + 8, 114);
    register.lineTo(center + 15, 114);
