  function travel(time, span, start, end, speedIn, speedOut) {
    const u = time / span;
    const distance = end - start;
    const a = speedIn * span;
    const b = speedOut * span;
    return start + u * (a + u * (3 * distance - 2 * a - b + u * (a + b - 2 * distance)));
