  function distanceAt(seconds) {
    if (seconds < scanStart) return travel(seconds, scanStart, 0, scanMark, seamSpeed, scanSpeed);
    if (seconds < scanEnd) return scanMark + (seconds - scanStart) * scanSpeed;
    if (seconds < returnStart) {
      return travel(seconds - scanEnd, returnStart - scanEnd, exitMark, returnMark, scanSpeed, returnSpeed);
    }
    return travel(seconds - returnStart, duration - returnStart, returnMark, railLength, returnSpeed, seamSpeed);
