  function trail(ctx, head, tail, alpha, unit, weight) {
    const endDistance = (head + railLength) % railLength;
    const startDistance = (endDistance - tail + railLength) % railLength;
    const wraps = startDistance > endDistance;
    const start = pointAt(startDistance);
    const end = pointAt(endDistance);
    const path = new Path2D();
    path.moveTo(start.x, start.y);

    const stop = wraps ? points.length : end.next;
    for (let i = start.next; i < stop; i++) path.lineTo(points[i].x, points[i].y);
    if (wraps) {
      for (let i = 1; i < end.next; i++) path.lineTo(points[i].x, points[i].y);
    }
    path.lineTo(end.x, end.y);

    const glow = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    glow.addColorStop(0, "rgba(233,141,83,0)");
    glow.addColorStop(0.4, "rgba(233,141,83,0.29)");
    glow.addColorStop(0.82, copper);
    glow.addColorStop(1, cream);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(255,212,166,0)");
    core.addColorStop(0.57, "rgba(255,212,166,0.35)");
    core.addColorStop(1, "#FFF0D7");

