    ctx.globalAlpha = alpha;
    ctx.shadowColor = "rgba(255,145,78,0.84)";
    ctx.shadowBlur = 18 * unit * weight;
    stroke(ctx, path, 5.8 * weight, glow);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.2 * weight, core);
    ctx.restore();
  }

  function indicator(ctx, path, power, unit) {
    stroke(ctx, path, 2.15, "#7F5039");
    if (power < 0.001) return;

    ctx.save();
    ctx.globalAlpha = power;
    ctx.shadowColor = "rgba(255,151,83,0.58)";
    ctx.shadowBlur = 9 * unit;
    stroke(ctx, path, 2.65, cream);
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#2B1913";
    ctx.fill(shell);

    ctx.shadowColor = "rgba(231,132,80,0.34)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, shell, 4.4, "#C17A53");
    ctx.shadowBlur = 0;
    stroke(ctx, shell, 1.25, "#FFC89B");
    stroke(ctx, inset, 1.9, "#86543D");
    stroke(ctx, rail, 2.0, "#835640");
    stroke(ctx, perforation, 2.5, "#916044");
    stroke(ctx, header, 3.6, "#AC7251");

    ctx.fillStyle = "#1C100D";
    ctx.fill(punch);
    stroke(ctx, punch, 2.7, "#B27655");
    stroke(ctx, punchBezel, 1.45, "#734A38");

    const barcode = ctx.createLinearGradient(0, -71, 0, 67);
    barcode.addColorStop(0, "#AD7652");
    barcode.addColorStop(1, "#7B4E37");
    ctx.fillStyle = barcode;
    ctx.fill(barField);

    ctx.fillStyle = cream;
    for (const bar of bars) {
      const age = seconds - bar.readAt;
      const headLight = envelope(age, -0.14, 0.12, 0.29, 0.9);
      const residual = 0.15 * ease(0.21, 0.59, age) * (1 - ease(11.72, 13.18, seconds));
      const light = Math.max(0.94 * headLight, residual);
