// Circuit Vault. Draw takes seconds and loops every 20 seconds.
// 4K export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintCircuitVault = (() => {
  const cyan = "#36E7FF";
  const ice = "#A6E9FF";

  function ease(from, to, value) {
    const u = Math.min(1, Math.max(0, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function envelope(value, fadeIn, full, hold, fadeOut) {
    return ease(fadeIn, full, value) * (1 - ease(hold, fadeOut, value));
  }

  // The measured centerline gives the light a consistent speed around curves.
  function rail(start, spans) {
    const path = new Path2D();
    path.moveTo(start[0], start[1]);
    const points = [{ x: start[0], y: start[1], distance: 0 }];

    for (const span of spans) {
      const origin = points[points.length - 1];
      if (span.length === 2) path.lineTo(...span);
      if (span.length === 4) path.quadraticCurveTo(...span);
      if (span.length === 6) path.bezierCurveTo(...span);

      const steps = span.length === 2 ? 1 : 48;
      for (let i = 1; i <= steps; i++) {
        const u = i / steps;
        const v = 1 - u;
        let x = span[0];
        let y = span[1];

        if (span.length === 4) {
          x = v * v * origin.x + 2 * v * u * span[0] + u * u * span[2];
          y = v * v * origin.y + 2 * v * u * span[1] + u * u * span[3];
        }
        if (span.length === 6) {
          x = v ** 3 * origin.x + 3 * v * v * u * span[0] + 3 * v * u * u * span[2] + u ** 3 * span[4];
          y = v ** 3 * origin.y + 3 * v * v * u * span[1] + 3 * v * u * u * span[3] + u ** 3 * span[5];
        }

        const last = points[points.length - 1];
        points.push({ x, y, distance: last.distance + Math.hypot(x - last.x, y - last.y) });
      }
    }

    return { path, points, length: points[points.length - 1].distance };
  }

  function pointAt(points, distance) {
    let low = 0;
    let high = points.length - 1;
    while (high - low > 1) {
      const middle = (high + low) >>> 1;
      if (points[middle].distance <= distance) low = middle;
      else high = middle;
    }
    const a = points[low];
    const b = points[high];
    const u = (distance - a.distance) / (b.distance - a.distance);
    return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u, next: high };
