    const start = pointAt(track.points, from);
    const end = pointAt(track.points, to);
    const path = new Path2D();
    path.moveTo(start.x, start.y);
    for (let i = start.next; i < end.next; i++) {
      path.lineTo(track.points[i].x, track.points[i].y);
    }
    path.lineTo(end.x, end.y);

    const tint = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    tint.addColorStop(0, "rgba(54,231,255,0)");
    tint.addColorStop(0.36, "rgba(54,231,255,0.22)");
    tint.addColorStop(0.76, "rgba(54,231,255,0.8)");
    tint.addColorStop(1, cyan);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(166,233,255,0)");
    core.addColorStop(0.58, "rgba(166,233,255,0.33)");
    core.addColorStop(0.9, ice);
    core.addColorStop(1, "#EFFCFF");

    ctx.save();
    ctx.globalAlpha = strength;
    ctx.shadowColor = "rgba(39,210,255,0.9)";
    ctx.shadowBlur = 21 * unit * weight;
    stroke(ctx, path, 6.4 * weight, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.5 * weight, core);
