    [92, -297, 162, -263, 226, -250],
    [258, -243, 258, -213],
    [258, -64],
    [258, 107, 164, 228, 22, 308]
  ]);

  const inner = rail([16, -280], [
    [90, -257, 151, -232, 207, -219],
    [222, -215, 222, -195],
    [222, -67],
    [222, 81, 145, 181, 18, 264]
  ]);

  const feed = rail([0, 212], [[0, 89]]);
  const branch = rail([92, -24], [
    [118, -24],
    [136, -24, 136, -42],
    [136, -155],
    [136, -176, 153, -186],
    [177, -200]
  ]);

  const crest = diamond(0, -323, 6);
  const receiver = diamond(0, 236, 9);
  const shoulder = diamond(187, -206, 5.3);
  const housing = new Path2D("M -44 -64 H 44 L 65 -43 V 37 L 44 58 H -44 L -65 37 V -43 Z");
  const inset = new Path2D("M -39 -50 H 39 L 51 -38 V 32 L 39 44 H -39 L -51 32 V -38 Z");
  const check = rail([-29, -2], [
    [-12, 15],
    [-8, 19, -4, 15],
    [30, -19]
  ]);

  const sideTicks = new Path2D(
    "M 173 -142 H 187 M 177 -120 H 187 M 181 -98 H 187 " +
    "M 173 32 H 185 M 166 53 H 180 M 158 74 H 173"
  );
  const feedTicks = new Path2D("M -17 161 H -11 M 11 161 H 17 M -17 140 H -11 M 11 140 H 17");

  function paintNode(ctx, path, intensity, unit) {
    ctx.fillStyle = "#0A1B28";
    ctx.fill(path);
    stroke(ctx, path, 2.4, "#477A94");
    if (intensity < 0.001) return;

    ctx.save();
    ctx.globalAlpha = intensity;
    ctx.shadowBlur = 11 * unit;
    ctx.shadowColor = "rgba(54,231,255,0.65)";
    stroke(ctx, path, 2.7, ice);
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#0A1B28";
    ctx.fill(shell);

    for (const side of [-1, 1]) {
      ctx.save();
      ctx.scale(side, 1);

      ctx.shadowBlur = 9 * unit;
      ctx.shadowColor = "rgba(54,198,255,0.26)";
      stroke(ctx, outer.path, 4.6, "#3A8AAB");
      ctx.shadowBlur = 0;
      stroke(ctx, outer.path, 1.2, "#8FD1E9");
      stroke(ctx, inner.path, 2.4, "#376479");
      stroke(ctx, sideTicks, 1.7, "#376173");
      stroke(ctx, branch.path, 2.1, "#3C748D");

      const carrier = (2 * progress + (side < 0 ? 0.10 : 0.56)) % 1;
      const carrierLight = 0.59 * envelope(carrier, 0, 0.11, 0.81, 1);
      trail(ctx, inner, carrier * (inner.length + 45), 70, carrierLight, unit, 0.68);

      const delay = side < 0 ? 0 : 0.19;
      pass(ctx, outer, seconds - delay, 0, 9.38, 128, 1, unit, 1);
      pass(ctx, branch, seconds - delay, 12.85, 19.65, 74, 0.93, unit, 0.77);
      const sent = envelope(seconds - delay, 17.75, 18.9, 19.13, 19.77);
      paintNode(ctx, shoulder, sent, unit);

      ctx.restore();
    }

    stroke(ctx, feed.path, 2.4, "#456E82");
    stroke(ctx, feedTicks, 1.65, "#385E73");
    pass(ctx, feed, seconds, 9.05, 12.65, 47, 0.96, unit, 0.82);
    paintNode(ctx, receiver, envelope(seconds, 8.45, 9.35, 9.68, 11.2), unit);
    paintNode(ctx, crest, 0.12 + 0.1 * Math.cos(2 * Math.PI * progress), unit);

    ctx.fillStyle = "#0B2030";
    ctx.fill(housing);
    stroke(ctx, housing, 3.1, "#568BA1");
    stroke(ctx, inset, 1.6, "#305C74");
    stroke(ctx, check.path, 3.5, "#488099");

    const verified = envelope(seconds, 11.62, 13.14, 14.45, 17.9);
    const checkHead = ease(11.62, 13.14, seconds) * check.length;
    trail(ctx, check, checkHead, 52, verified, unit, 0.92);

    ctx.save();
    ctx.globalAlpha = verified * ease(12.7, 13.5, seconds);
    ctx.shadowBlur = 12 * unit;
    ctx.shadowColor = "rgba(54,231,255,0.58)";
    stroke(ctx, check.path, 3.2, ice);
    ctx.restore();
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1000;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#06121E";
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.501);
  ctx.scale(unit, unit);
  paintCircuitVault(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}

// Charge Cascade. Draw takes seconds and loops every 20 seconds.
// 4K export target is 3840 × 2160 at 100,000 kbps CBR in the video encoder.

const paintChargeCascade = (() => {
  const lime = "#A7FF35";
  const citron = "#F0FF9C";

  function ease(from, to, value) {
    const u = Math.min(1, Math.max(0, (value - from) / (to - from)));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  const shell = new Path2D(
    "M -473 -188 H 429 Q 486 -188 486 -131 V -62 H 520 " +
    "Q 551 -62 551 -30 V 30 Q 551 62 520 62 H 486 V 131 " +
    "Q 486 188 429 188 H -473 Q -535 188 -535 126 V -126 Q -535 -188 -473 -188 Z"
  );
  const inset = new Path2D(
    "M -466 -162 H 423 Q 461 -162 461 -123 V -64 Q 461 -48 477 -48 " +
    "H 516 Q 537 -48 537 -28 V 28 Q 537 48 516 48 H 477 Q 461 48 461 64 " +
    "V 123 Q 461 162 423 162 H -466 Q -509 162 -509 119 V -119 Q -509 -162 -466 -162 Z"
  );
  const terminal = new Path2D("M 489 -8 V 8 M 500 -8 V 8");

  const cellX = -453;
  const cellY = -87;
  const cellWidth = 128;
  const cellHeight = 172;
  const pitch = 146;
  const cellCount = 6;
  const firstArrival = 3.08;
  const lastArrival = 11.64;
  const terminalArrival = 14.05;
  const topY = -129;

  const ticks = new Path2D();
  const cells = [];
  for (let i = 0; i < cellCount; i++) {
    const x = cellX + i * pitch;
    const center = x + cellWidth / 2;
    const shellPath = new Path2D();
    shellPath.roundRect(x, cellY, cellWidth, cellHeight, 17);

    const windowPath = new Path2D();
    windowPath.roundRect(x + 8, cellY + 8, cellWidth - 16, cellHeight - 16, 12);

    const indicator = new Path2D();
    indicator.moveTo(center - 7, -109);
    indicator.lineTo(center + 7, -109);

    for (const offset of [-11, 0, 11]) {
      ticks.moveTo(center + offset, 140);
      ticks.lineTo(center + offset, offset === 0 ? 148 : 144);
    }
    cells.push({ x, shellPath, windowPath, indicator });
  }

  // Sample the closed rail once so the current keeps its speed around bends.
  const spans = [
    [-455, 121], [-483, 121, -483, 93], [-483, -101], [-483, topY, -455, topY],
    [410, topY], [438, topY, 438, -101], [438, -60], [438, -36, 462, -36],
    [491, -36], [520, -36, 520, -9], [520, 9], [520, 36, 493, 36],
    [468, 36], [440, 36, 440, 64], [440, 93], [440, 121, 412, 121], [-285, 121]
  ];

  const rail = new Path2D();
  rail.moveTo(-285, 121);
  const samples = [{ x: -285, y: 121, distance: 0 }];
  const marks = [];

  for (const span of spans) {
    const origin = samples[samples.length - 1];
    const isCurve = span.length === 4;
    if (isCurve) rail.quadraticCurveTo(...span);
    else rail.lineTo(...span);

    const steps = isCurve ? 32 : 1;
    for (let i = 1; i <= steps; i++) {
      const u = i / steps;
      const v = 1 - u;
      const x = isCurve ? v * v * origin.x + 2 * v * u * span[0] + u * u * span[2] : span[0];
      const y = isCurve ? v * v * origin.y + 2 * v * u * span[1] + u * u * span[3] : span[1];
      const last = samples[samples.length - 1];
      samples.push({ x, y, distance: last.distance + Math.hypot(x - last.x, y - last.y) });
    }
    marks.push(samples[samples.length - 1].distance);
  }

  const railLength = samples[samples.length - 1].distance;
  const firstCellMark = marks[3] + cellX + cellWidth / 2 + 455;
  const lastCellMark = firstCellMark + (cellCount - 1) * pitch;
  const terminalMark = marks[9] + 9;
  const cruiseSpeed = (lastCellMark - firstCellMark) / (lastArrival - firstArrival);
  const terminalSpeed = 130;
  const seamSpeed = 170;

  // Matching tangents keep the current smooth at every phase boundary.
  function travel(elapsed, span, start, end, speedIn, speedOut) {
    const u = elapsed / span;
    const delta = end - start;
    const a = speedIn * span;
    const b = speedOut * span;
    return start + u * (a + u * ((3 * delta - 2 * a - b) + u * (a + b - 2 * delta)));
  }

  function distanceAt(seconds) {
    if (seconds < firstArrival) {
      return travel(seconds, firstArrival, 0, firstCellMark, seamSpeed, cruiseSpeed);
    }
    if (seconds < lastArrival) {
      return firstCellMark + (seconds - firstArrival) * cruiseSpeed;
    }
    if (seconds < terminalArrival) {
      return travel(seconds - lastArrival, terminalArrival - lastArrival, lastCellMark, terminalMark,
        cruiseSpeed, terminalSpeed);
    }
    return travel(seconds - terminalArrival, 20 - terminalArrival, terminalMark, railLength,
      terminalSpeed, seamSpeed);
  }

  function pointAt(distance) {
    let low = 0;
    let high = samples.length - 1;
    while (high - low > 1) {
      const middle = (high + low) >>> 1;
      if (samples[middle].distance <= distance) low = middle;
      else high = middle;
    }
    const a = samples[low];
    const b = samples[high];
    const u = (distance - a.distance) / (b.distance - a.distance);
    return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u, next: high };
  }

  function stroke(ctx, path, width, color) {
    ctx.lineWidth = width;
    ctx.strokeStyle = color;
    ctx.stroke(path);
  }

  function trail(ctx, head, tailLength, alpha, unit, weight) {
    const endDistance = (head + railLength) % railLength;
    const startDistance = (endDistance - tailLength + railLength) % railLength;
    const wraps = startDistance > endDistance;
    const start = pointAt(startDistance);
    const end = pointAt(endDistance);
    const path = new Path2D();
    path.moveTo(start.x, start.y);
    const stop = wraps ? samples.length : end.next;
    for (let i = start.next; i < stop; i++) {
      path.lineTo(samples[i].x, samples[i].y);
    }
    if (wraps) {
      for (let i = 1; i < end.next; i++) {
        path.lineTo(samples[i].x, samples[i].y);
      }
    }
    path.lineTo(end.x, end.y);

    const tint = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    tint.addColorStop(0, "rgba(167,255,53,0)");
    tint.addColorStop(0.34, "rgba(167,255,53,0.17)");
    tint.addColorStop(0.78, "rgba(167,255,53,0.8)");
    tint.addColorStop(1, lime);

    const core = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
    core.addColorStop(0, "rgba(240,255,156,0)");
    core.addColorStop(0.58, "rgba(240,255,156,0.3)");
    core.addColorStop(1, "#FCFFDF");

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.shadowBlur = 14 * unit * weight;
    ctx.shadowColor = "rgba(158,255,66,0.83)";
    stroke(ctx, path, 5.4 * weight, tint);
    ctx.shadowBlur = 0;
    stroke(ctx, path, 2.15 * weight, core);
    ctx.restore();
  }

  function paintCell(ctx, cell, i, seconds, progress, cavity) {
    const arrival = firstArrival + (lastArrival - firstArrival) * i / (cellCount - 1);
    const release = 14.28 + (cellCount - 1 - i) * 0.55;
    const stored = ease(arrival, arrival + 2.36, seconds);
    const spent = ease(release, release + 2.33, seconds);
    const level = stored * (1 - spent);

    ctx.fillStyle = cavity;
    ctx.fill(cell.shellPath);
    stroke(ctx, cell.shellPath, 2.35, "#536943");
    stroke(ctx, cell.indicator, 2.15, "#62764B");

    if (level <= 0.001) return;

    const left = cell.x + 8;
    const windowWidth = cellWidth - 16;
    const floor = cellY + cellHeight - 9;
    const fillHeight = (cellHeight - 21) * level;
    const surface = floor - fillHeight;
    const visibility = ease(0.001, 0.07, level);

    ctx.save();
    ctx.globalAlpha = visibility;
    ctx.clip(cell.windowPath);

    const charge = ctx.createLinearGradient(0, surface, 0, floor);
    charge.addColorStop(0, "#88B840");
    charge.addColorStop(0.2, "#5E852D");
    charge.addColorStop(1, "#273B16");
    ctx.fillStyle = charge;
    ctx.fillRect(left, surface, windowWidth, fillHeight);

    const sweep = (3 * progress + 1 - i * 0.13) % 1;
    const sweepX = left - 32 + (windowWidth + 64) * sweep;
    const sheen = ctx.createLinearGradient(sweepX - 25, 0, sweepX + 25, 0);
    sheen.addColorStop(0, "rgba(225,255,155,0)");
    sheen.addColorStop(0.5, "rgba(225,255,155,0.24)");
    sheen.addColorStop(1, "rgba(225,255,155,0)");
    ctx.fillStyle = sheen;
    ctx.fillRect(left, surface, windowWidth, fillHeight);

    const meniscus = ctx.createLinearGradient(0, surface - 7, 0, surface + 12);
    meniscus.addColorStop(0, "rgba(167,255,53,0)");
    meniscus.addColorStop(0.34, "rgba(167,255,53,0.32)");
    meniscus.addColorStop(0.47, citron);
    meniscus.addColorStop(0.57, "rgba(199,255,96,0.65)");
    meniscus.addColorStop(1, "rgba(167,255,53,0)");
    ctx.fillStyle = meniscus;
    ctx.fillRect(left, surface - 7, windowWidth, 19);
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = visibility * (0.25 + 0.54 * level);
    stroke(ctx, cell.shellPath, 1.85, "#99C75E");
    stroke(ctx, cell.indicator, 2.75, citron);
    ctx.restore();
  }

  return function paint(ctx, seconds, progress, unit) {
    ctx.fillStyle = "#152012";
    ctx.fill(shell);

    ctx.shadowColor = "rgba(164,239,81,0.32)";
    ctx.shadowBlur = 9 * unit;
    stroke(ctx, shell, 4.5, "#74994D");
    ctx.shadowBlur = 0;
    stroke(ctx, shell, 1.2, "#BBD785");
    stroke(ctx, inset, 2.1, "#415835");
    stroke(ctx, rail, 2.05, "#4B6136");
    stroke(ctx, ticks, 1.55, "#576843");
    stroke(ctx, terminal, 2.2, "#647D4E");

    const cavity = ctx.createLinearGradient(0, cellY, 0, cellY + cellHeight);
    cavity.addColorStop(0, "#142211");
    cavity.addColorStop(1, "#0B150A");
    for (let i = 0; i < cells.length; i++) {
      paintCell(ctx, cells[i], i, seconds, progress, cavity);
    }

    const head = distanceAt(seconds);
    trail(ctx, head - 158, 57, 0.44, unit, 0.66);
    trail(ctx, head, 125, 1, unit, 1);

    const output = ease(13.67, 14.33, seconds) * (1 - ease(17.3, 19.05, seconds));
    ctx.save();
    ctx.globalAlpha = output * (0.9 + 0.1 * Math.cos(8 * Math.PI * progress));
    ctx.shadowColor = "rgba(181,255,94,0.66)";
    ctx.shadowBlur = 10 * unit;
    stroke(ctx, terminal, 3.1, citron);
    ctx.restore();
  };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const sceneTime = loopT - currentScene * sceneDuration;

  const minSide = Math.min(width, height);
  const unit = minSide / 1000;

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.filter = "none";
  ctx.shadowColor = "transparent";
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.setLineDash([]);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  ctx.fillStyle = "#11180B";
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5 + 12 * unit, height * 0.5);
  ctx.scale(unit, unit);
  paintChargeCascade(ctx, sceneTime, sceneProgress, unit);
  ctx.restore();
}
